import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { 
  Home, 
  Film, 
  Users, 
  PlusCircle, 
  User, 
  LogOut, 
  Menu, 
  X,
  BookOpen,
  Clock,
  Settings
} from 'lucide-react';

const Navbar = () => {
  const { isAuthenticated, user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Check if user is admin
  const isAdmin = user?.email === 'admin@example.com' || user?.username === 'admin';

  const handleLogout = () => {
    logout();
    navigate('/login');
    setIsMobileMenuOpen(false);
  };

  const isActivePath = (path) => {
    return location.pathname === path;
  };

  const navItems = [
    { path: '/', label: 'Dashboard', icon: Home },
    { path: '/series', label: 'Series', icon: Film },
    { path: '/series/new', label: 'Create Series', icon: PlusCircle },
    { path: '/tutorials', label: 'Tutorials', icon: BookOpen },
    ...(isAdmin ? [{ path: '/admin', label: 'Admin', icon: Settings }] : []),
  ];

  return (
    <nav className="bg-gradient-to-r from-white via-primary-50 to-secondary-50 shadow-lg border-b border-primary-100 backdrop-blur-lg sticky top-0 z-50">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link 
            to="/" 
            className="group flex items-center space-x-3 text-xl font-bold gradient-text hover:scale-105 transition-transform duration-300"
          >
            <div className="p-2 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-xl shadow-lg group-hover:shadow-xl transition-shadow duration-300">
              <Film className="w-6 h-6 text-white" />
            </div>
            <span className="tracking-tight">VideoSeries</span>
          </Link>

          {/* Desktop Navigation */}
          {isAuthenticated && (
            <div className="hidden md:flex items-center space-x-2">
              {navItems.map((item) => {
                const Icon = item.icon;
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    className={`group flex items-center space-x-2 px-4 py-2 rounded-xl text-sm font-semibold transition-all duration-300 ${
                      isActivePath(item.path)
                        ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white shadow-lg transform scale-105'
                        : 'text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-primary-500 hover:to-secondary-500 hover:shadow-lg hover:scale-105'
                    }`}
                  >
                    <Icon className="w-4 h-4 group-hover:animate-bounce" />
                    <span>{item.label}</span>
                  </Link>
                );
              })}
            </div>
          )}

          {/* User Menu */}
          {isAuthenticated && (
            <div className="hidden md:flex items-center space-x-3">
              {/* Session Indicator */}
              <div className="flex items-center space-x-2 px-3 py-1.5 bg-gradient-to-r from-amber-50 to-amber-100 border border-amber-200 rounded-xl shadow-sm">
                <Clock className="w-4 h-4 text-amber-600 animate-pulse" />
                <span className="text-xs text-amber-700 font-semibold">Session</span>
              </div>

              <Link
                to="/profile"
                className="group flex items-center space-x-2 px-4 py-2 text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-primary-500 hover:to-secondary-500 rounded-xl transition-all duration-300 shadow-sm hover:shadow-lg"
              >
                <div className="p-1.5 bg-gray-100 group-hover:bg-white rounded-lg transition-colors">
                  <User className="w-4 h-4" />
                </div>
                <span className="text-sm font-medium">
                  {user?.profile?.firstName || user?.username}
                </span>
              </Link>
              <button
                onClick={handleLogout}
                className="group flex items-center space-x-2 px-4 py-2 text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-red-500 hover:to-red-600 rounded-xl transition-all duration-300 shadow-sm hover:shadow-lg"
              >
                <div className="p-1.5 bg-gray-100 group-hover:bg-white rounded-lg transition-colors">
                  <LogOut className="w-4 h-4" />
                </div>
                <span className="text-sm font-medium">Logout</span>
              </button>
            </div>
          )}

          {/* Mobile menu button */}
          {isAuthenticated && (
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-3 rounded-xl text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-primary-500 hover:to-secondary-500 transition-all duration-300 shadow-sm hover:shadow-lg"
            >
              {isMobileMenuOpen ? (
                <X className="w-6 h-6" />
              ) : (
                <Menu className="w-6 h-6" />
              )}
            </button>
          )}
        </div>

        {/* Mobile Navigation */}
        {isAuthenticated && isMobileMenuOpen && (
          <div className="md:hidden py-4 border-t border-primary-100 bg-gradient-to-b from-primary-50 to-white">
            <div className="flex flex-col space-y-2">
              {navItems.map((item) => {
                const Icon = item.icon;
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className={`group flex items-center space-x-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all duration-300 ${
                      isActivePath(item.path)
                        ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white shadow-lg'
                        : 'text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-primary-500 hover:to-secondary-500 hover:shadow-lg'
                    }`}
                  >
                    <Icon className="w-5 h-5 group-hover:animate-bounce" />
                    <span>{item.label}</span>
                  </Link>
                );
              })}
              <div className="border-t border-primary-200 pt-4 mt-2">
                {/* Session Indicator for Mobile */}
                <div className="flex items-center space-x-3 px-4 py-3 bg-gradient-to-r from-amber-50 to-amber-100 border border-amber-200 rounded-xl mb-3">
                  <Clock className="w-4 h-4 text-amber-600 animate-pulse" />
                  <span className="text-xs text-amber-700 font-semibold">Session Active - Login expires on refresh</span>
                </div>

                <Link
                  to="/profile"
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="group flex items-center space-x-3 px-4 py-3 rounded-xl text-sm font-semibold text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-primary-500 hover:to-secondary-500 hover:shadow-lg transition-all duration-300"
                >
                  <User className="w-5 h-5 group-hover:animate-bounce" />
                  <span>Profile</span>
                </Link>
                <button
                  onClick={handleLogout}
                  className="w-full group flex items-center space-x-3 px-4 py-3 rounded-xl text-sm font-semibold text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-red-500 hover:to-red-600 hover:shadow-lg transition-all duration-300 text-left"
                >
                  <LogOut className="w-5 h-5 group-hover:animate-bounce" />
                  <span>Logout</span>
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
